// FulfillmentStatusContainsFold applies the ContainsFold predicate on the "fulfillment_status" field.
func FulfillmentStatusContainsFold(v string) predicate.OrderItem {
	return predicate.OrderItem(sql.FieldContainsFold(FieldFulfillmentStatus, v))
}

// CommissionSnapshotIsNil applies the IsNil predicate on the "commission_snapshot" field.
func CommissionSnapshotIsNil() predicate.OrderItem {
	return predicate.OrderItem(sql.FieldIsNull(FieldCommissionSnapshot))
}

// CommissionSnapshotNotNil applies the NotNil predicate on the "commission_snapshot" field.
func CommissionSnapshotNotNil() predicate.OrderItem {
	return predicate.OrderItem(sql.FieldNotNull(FieldCommissionSnapshot))
}

// ProfitSnapshotIsNil applies the IsNil predicate on the "profit_snapshot" field.
func ProfitSnapshotIsNil() predicate.OrderItem {
	return predicate.OrderItem(sql.FieldIsNull(FieldProfitSnapshot))
}

// ProfitSnapshotNotNil applies the NotNil predicate on the "profit_snapshot" field.
func ProfitSnapshotNotNil() predicate.OrderItem {
	return predicate.OrderItem(sql.FieldNotNull(FieldProfitSnapshot))
}

// HasOrder applies the HasEdge predicate on the "order" edge.
func HasOrder() predicate.OrderItem {
	return predicate.OrderItem(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, OrderTable, OrderColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasOrderWith applies the HasEdge predicate on the "order" edge with a given conditions (other predicates).
func HasOrderWith(preds ...predicate.Order) predicate.OrderItem {
	return predicate.OrderItem(func(s *sql.Selector) {
		step := newOrderStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.OrderItem) predicate.OrderItem {
	return predicate.OrderItem(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.OrderItem) predicate.OrderItem {
	return predicate.OrderItem(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.OrderItem) predicate.OrderItem {
	return predicate.OrderItem(sql.NotPredicates(p))
}
